package org.brightstats.report;

import com.google.gson.*;
import java.util.*;
import javafx.scene.Node;
import javafx.scene.Parent;
import javafx.scene.chart.*;
import javafx.scene.control.ScrollPane;

/** Self-contained vector exports from diagram coordinates and JavaFX chart data, never screenshots. */
public final class SvgGraphics {
    private SvgGraphics(){}
    private static final String[] COLORS={"#d94c21","#176ba0","#258039","#7851a9","#a65e00","#a5235f","#237e83"};
    private static String escape(String value){return XmlText.escape(value);}
    private static String number(double value){if(!Double.isFinite(value))throw new IllegalArgumentException("Nonfinite graphic coordinate.");return Double.toString(value);}
    private static String label(double value){return String.format(Locale.ROOT,value!=0&&(Math.abs(value)<.001||Math.abs(value)>=100000)?"%.3e":"%.4g",value);}
    private static void text(StringBuilder out,double x,double y,String value,int size,String anchor){out.append("<text x=\"").append(number(x)).append("\" y=\"").append(number(y)).append("\" font-size=\"").append(size).append("\" text-anchor=\"").append(anchor).append("\">").append(escape(value)).append("</text>");}
    private static StringBuilder start(int width,int height,String title){return new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"").append(width).append("\" height=\"").append(height).append("\" viewBox=\"0 0 ").append(width).append(' ').append(height).append("\" role=\"img\" aria-label=\"").append(escape(title)).append("\"><title>").append(escape(title)).append("</title><rect width=\"100%\" height=\"100%\" fill=\"white\"/><g font-family=\"sans-serif\" fill=\"#163a50\">");}
    public static String diagram(JsonObject graph,String title,double[][] coefficients){JsonArray blocks=graph.getAsJsonArray("blocks"),edges=graph.getAsJsonArray("edges");double maxX=900,maxY=600;for(var element:blocks){var block=element.getAsJsonObject();maxX=Math.max(maxX,block.get("x").getAsDouble()+120);maxY=Math.max(maxY,block.get("y").getAsDouble()+100);}if(maxX>20000||maxY>20000)throw new IllegalArgumentException("Diagram export dimensions exceed 20,000 units.");StringBuilder out=start((int)Math.ceil(maxX),(int)Math.ceil(maxY+50),title);out.append("<defs><marker id=\"arrow\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\"><path d=\"M0,0 L0,6 L8,3 z\" fill=\"#376985\"/></marker></defs>");text(out,20,26,title,18,"start");out.append("<metadata>").append(escape(graph.toString())).append("</metadata>");for(var element:edges){var edge=element.getAsJsonObject();int source=edge.get("source").getAsBigDecimal().intValueExact(),target=edge.get("target").getAsBigDecimal().intValueExact();if(source<0||target<0||source>=blocks.size()||target>=blocks.size())throw new IllegalArgumentException("Invalid diagram export edge.");var a=blocks.get(source).getAsJsonObject();var b=blocks.get(target).getAsJsonObject();double ax=a.get("x").getAsDouble(),ay=a.get("y").getAsDouble()+40,bx=b.get("x").getAsDouble(),by=b.get("y").getAsDouble()+40,dx=bx-ax,dy=by-ay,norm=Math.sqrt(dx*dx/(76*76)+dy*dy/(48*48));if(norm==0)continue;double offset=1/norm;out.append("<line x1=\"").append(number(ax+dx*offset)).append("\" y1=\"").append(number(ay+dy*offset)).append("\" x2=\"").append(number(bx-dx*offset)).append("\" y2=\"").append(number(by-dy*offset)).append("\" stroke=\"#376985\" stroke-width=\"2\" marker-end=\"url(#arrow)\"/>");if(coefficients!=null&&Double.isFinite(coefficients[source][target]))text(out,(ax+bx)/2+4,(ay+by)/2-6,label(coefficients[source][target]),12,"start");}for(var element:blocks){var block=element.getAsJsonObject();double x=block.get("x").getAsDouble(),y=block.get("y").getAsDouble()+40;out.append("<ellipse cx=\"").append(number(x)).append("\" cy=\"").append(number(y)).append("\" rx=\"76\" ry=\"48\" fill=\"#edf8fb\" stroke=\"#2d688b\" stroke-width=\"2\"/>");text(out,x,y-3,block.get("name").getAsString(),15,"middle");text(out,x,y+20,block.getAsJsonArray("columns").size()+" indicators · Mode "+block.get("mode").getAsString(),11,"middle");}return out.append("</g></svg>").toString();}
    private static void collect(Node node,List<XYChart<?,?>> charts){if(node instanceof XYChart<?,?> chart){charts.add(chart);return;}if(node instanceof ScrollPane scroll){collect(scroll.getContent(),charts);return;}if(node instanceof Parent parent)for(Node child:parent.getChildrenUnmodifiable())collect(child,charts);}
    private static List<String> categories(Axis<?> axis,XYChart<?,?> chart,boolean x){if(axis instanceof NumberAxis)return List.of();LinkedHashSet<String> values=new LinkedHashSet<>();if(axis instanceof CategoryAxis category)values.addAll(category.getCategories());for(var series:chart.getData())for(var point:series.getData())values.add(String.valueOf(x?point.getXValue():point.getYValue()));return List.copyOf(values);}
    private static double coordinate(Object value,List<String> categories,double minimum,double maximum,double origin,double length,boolean invert){double fraction;if(categories.isEmpty()){if(!(value instanceof Number numeric)||!Double.isFinite(numeric.doubleValue()))return Double.NaN;fraction=(numeric.doubleValue()-minimum)/(maximum-minimum);}else{int index=categories.indexOf(String.valueOf(value));if(index<0)return Double.NaN;fraction=(index+.5)/categories.size();}return origin+(invert?1-fraction:fraction)*length;}
    private static double lower(Axis<?> axis){return axis instanceof NumberAxis number?number.getLowerBound():0;}
    private static double upper(Axis<?> axis){if(axis instanceof NumberAxis number)return number.getUpperBound()>number.getLowerBound()?number.getUpperBound():number.getLowerBound()+1;return 1;}
    private static JsonObject chartMetadata(XYChart<?,?> chart){JsonObject result=new JsonObject();result.addProperty("type",chart.getClass().getSimpleName());result.addProperty("title",chart.getTitle());result.addProperty("xLabel",chart.getXAxis().getLabel());result.addProperty("yLabel",chart.getYAxis().getLabel());result.addProperty("xLower",lower(chart.getXAxis()));result.addProperty("xUpper",upper(chart.getXAxis()));result.addProperty("yLower",lower(chart.getYAxis()));result.addProperty("yUpper",upper(chart.getYAxis()));JsonArray series=new JsonArray();int metadataIndex=0;for(var original:chart.getData()){JsonObject item=new JsonObject();item.addProperty("name",original.getName());item.addProperty("hidden",chart.getProperties().get("brightstats.hiddenSeries") instanceof Set<?> hidden&&hidden.contains(metadataIndex));metadataIndex++;JsonArray points=new JsonArray();for(var point:original.getData()){JsonObject value=new JsonObject();Object x=point.getXValue(),y=point.getYValue();if(x instanceof Number number&&Double.isFinite(number.doubleValue()))value.addProperty("x",number.doubleValue());else value.addProperty("x",String.valueOf(x));if(y instanceof Number number&&Double.isFinite(number.doubleValue()))value.addProperty("y",number.doubleValue());else value.addProperty("y",String.valueOf(y));if(point.getExtraValue()!=null)value.addProperty("label",point.getExtraValue().toString());if(point.getExtraValue() instanceof GraphicPoint source){value.add("sourceRows",new Gson().toJsonTree(source.rows()));value.add("sourceColumns",new Gson().toJsonTree(source.columns()));value.addProperty("rowSpace",source.rowSpace().name());}points.add(value);}item.add("points",points);series.add(item);}result.add("series",series);return result;}
    public static String nca(org.brightstats.stats.Nca.Fit fit,double[][] predictors,double[] outcome){if(fit.conditions().size()>30||(long)outcome.length*fit.conditions().size()>1000000L)throw new IllegalArgumentException("NCA vector export exceeds 30 panels or one million plotted observations.");StringBuilder out=start(1100,70+fit.conditions().size()*520,"Necessary-condition ceiling plots");text(out,20,28,"Necessary-condition ceiling plots",18,"start");text(out,20,49,"Observations: blue · CE-FDH: teal steps · CR-FDH: orange dashed · consult the report for assumptions",11,"start");for(int index=0;index<fit.conditions().size();index++){var condition=fit.conditions().get(index);var xs=condition.scope();var ys=fit.outcomeScope();double left=110,top=100+index*520,w=900,h=320;java.util.function.DoubleUnaryOperator px=value->left+w*(value-xs.minimum())/xs.range(),py=value->top+h-h*(value-ys.minimum())/ys.range();text(out,left,top-20,condition.name()+" → "+fit.outcomeName(),16,"start");out.append("<defs><clipPath id=\"nca-").append(index).append("\"><rect x=\"").append(number(left)).append("\" y=\"").append(number(top)).append("\" width=\"").append(number(w)).append("\" height=\"").append(number(h)).append("\"/></clipPath></defs>");JsonObject data=new JsonObject();data.addProperty("condition",condition.name());data.addProperty("outcome",fit.outcomeName());JsonArray points=new JsonArray();for(int row=0;row<outcome.length;row++){JsonArray point=new JsonArray();point.add(predictors[row][index]);point.add(outcome[row]);points.add(point);}data.add("observations",points);data.add("ceiling",new Gson().toJsonTree(condition.ceilingPoints()));out.append("<metadata>").append(escape(data.toString())).append("</metadata>");for(int tick=0;tick<=5;tick++){double x=xs.minimum()+xs.range()*tick/5,y=ys.minimum()+ys.range()*tick/5;out.append("<path d=\"M").append(number(px.applyAsDouble(x))).append(' ').append(number(top)).append(" v").append(number(h)).append(" M").append(number(left)).append(' ').append(number(py.applyAsDouble(y))).append(" h").append(number(w)).append("\" fill=\"none\" stroke=\"#dce4e8\"/>");text(out,px.applyAsDouble(x),top+h+22,label(x),11,"middle");text(out,left-12,py.applyAsDouble(y)+4,label(y),11,"end");}text(out,left+w/2,top+h+60,condition.name()+" (condition)",12,"middle");out.append("<text x=\"22\" y=\"").append(number(top+h/2)).append("\" font-size=\"12\" text-anchor=\"middle\" transform=\"rotate(-90 22 ").append(number(top+h/2)).append(")\">").append(escape(fit.outcomeName())).append("</text><g clip-path=\"url(#nca-").append(index).append(")\">");for(int row=0;row<outcome.length;row++)out.append("<circle cx=\"").append(number(px.applyAsDouble(predictors[row][index]))).append("\" cy=\"").append(number(py.applyAsDouble(outcome[row]))).append("\" r=\"2\" fill=\"#2563ab\" fill-opacity=\"0.6\"/>");StringBuilder path=new StringBuilder("M"+number(left)+" "+number(top+h));for(var point:condition.ceilingPoints())path.append('H').append(number(px.applyAsDouble(point.x()))).append('V').append(number(py.applyAsDouble(point.y())));path.append('H').append(number(left+w));out.append("<path d=\"").append(path).append("\" fill=\"none\" stroke=\"#087f75\" stroke-width=\"2\"/>");var line=condition.crFdh();if(line.regressionAvailable()&&Double.isFinite(line.slope())&&Double.isFinite(line.intercept())&&line.slope()>0){double start=Math.max(xs.minimum(),(ys.minimum()-line.intercept())/line.slope()),end=Math.min(xs.maximum(),(ys.maximum()-line.intercept())/line.slope());if(end>=start)out.append("<line x1=\"").append(number(px.applyAsDouble(start))).append("\" y1=\"").append(number(py.applyAsDouble(line.slope()*start+line.intercept()))).append("\" x2=\"").append(number(px.applyAsDouble(end))).append("\" y2=\"").append(number(py.applyAsDouble(line.slope()*end+line.intercept()))).append("\" stroke=\"#cb6b0a\" stroke-width=\"2\" stroke-dasharray=\"7 4\"/>");}out.append("</g>");}return out.append("</g></svg>").toString();}
    private static void appendRibbon(StringBuilder out,XYChart<?,?> chart,double xLow,double xHigh,double yLow,double yHigh,double left,double top,double width,double height){if(!(chart.getProperties().get("brightstats.ribbon") instanceof List<?> raw))return;JsonArray source=new JsonArray();List<double[]> rows=new ArrayList<>();for(Object value:raw)if(value instanceof double[] row&&row.length==3&&Arrays.stream(row).allMatch(Double::isFinite)){rows.add(row);source.add(new Gson().toJsonTree(row));}out.append("<metadata>").append(escape("{\"format\":\"bright-stats-uncertainty-ribbon\",\"columns\":[\"testedN\",\"wilsonLower95\",\"wilsonUpper95\"],\"rows\":"+source+"}")).append("</metadata>");if(rows.size()<2||chart.getProperties().get("brightstats.hiddenSeries") instanceof Set<?> hidden&&(hidden.contains(1)||hidden.contains(2)))return;StringBuilder path=new StringBuilder();for(int i=0;i<rows.size()*2;i++){double[] row=rows.get(i<rows.size()?i:rows.size()*2-1-i);double x=left+width*(row[0]-xLow)/(xHigh-xLow),y=top+height-height*(row[i<rows.size()?1:2]-yLow)/(yHigh-yLow);path.append(i==0?'M':'L').append(number(x)).append(' ').append(number(y)).append(' ');}out.append("<path d=\"").append(path).append("Z\" fill=\"#228bb8\" fill-opacity=\"0.19\"><title>Wilson 95% finite-replicate uncertainty; connecting edges are visual guides only.</title></path>");}
    private static String custom(Node node){Object supplier=node.getProperties().get("brightstats.svg");if(supplier instanceof java.util.function.Supplier<?> factory){Object value=factory.get();if(value instanceof String svg)return svg;}if(node instanceof ScrollPane scroll)return custom(scroll.getContent());return null;}
    public static String charts(Node node,String title){String custom=custom(node);if(custom!=null)return custom;List<XYChart<?,?>> charts=new ArrayList<>();collect(node,charts);if(charts.isEmpty())throw new IllegalArgumentException("Select a chart tab before exporting SVG.");if(charts.size()>30)throw new IllegalArgumentException("Export at most 30 charts at once.");int width=1100;int[] panels=charts.stream().mapToInt(chart->Math.max(520,460+20*((chart.getData().size()+2)/3))).toArray();StringBuilder out=start(width,70+Arrays.stream(panels).sum(),title);text(out,20,28,title,18,"start");text(out,20,49,"Bright-Stats vector export · original chart data and displayed axis bounds · consult the saved report for assumptions",11,"start");for(int chartIndex=0;chartIndex<charts.size();chartIndex++){XYChart<?,?> chart=charts.get(chartIndex);chart.applyCss();chart.layout();double left=110,top=100+Arrays.stream(panels,0,chartIndex).sum(),plotWidth=900,plotHeight=320;Axis<?> xAxis=chart.getXAxis(),yAxis=chart.getYAxis();List<String> xs=categories(xAxis,chart,true),ys=categories(yAxis,chart,false);if(!ys.isEmpty()){int longest=ys.stream().mapToInt(String::length).max().orElse(0);left=Math.min(460,Math.max(110,longest*6.5+20));plotWidth=width-left-60;}double xLow=lower(xAxis),xHigh=upper(xAxis),yLow=lower(yAxis),yHigh=upper(yAxis);text(out,left,top-20,chart.getTitle()==null?"Chart "+(chartIndex+1):chart.getTitle(),16,"start");out.append("<metadata>").append(escape(chartMetadata(chart).toString())).append("</metadata>");out.append("<defs><clipPath id=\"plot-").append(chartIndex).append("\"><rect x=\"").append(number(left)).append("\" y=\"").append(number(top)).append("\" width=\"").append(number(plotWidth)).append("\" height=\"").append(number(plotHeight)).append("\"/></clipPath></defs>");for(int tick=0;tick<=5;tick++){double y=top+plotHeight*tick/5;out.append("<line x1=\"").append(number(left)).append("\" x2=\"").append(number(left+plotWidth)).append("\" y1=\"").append(number(y)).append("\" y2=\"").append(number(y)).append("\" stroke=\"#dce4e8\"/>");if(ys.isEmpty())text(out,left-12,y+4,label(yHigh-(yHigh-yLow)*tick/5),11,"end");if(xs.isEmpty())text(out,left+plotWidth*tick/5,top+plotHeight+22,label(xLow+(xHigh-xLow)*tick/5),11,"middle");}if(!ys.isEmpty())for(int index=0;index<ys.size();index++){String full=ys.get(index);int maximum=Math.max(10,(int)((left-35)/6.5));String shown=full.length()>maximum?full.substring(0,maximum-1)+"…":full;double categoryY=top+plotHeight*(1-(index+.5)/ys.size());out.append("<text x=\"").append(number(left-12)).append("\" y=\"").append(number(categoryY+4)).append("\" font-size=\"11\" text-anchor=\"end\" aria-label=\"").append(escape(full)).append("\"><title>").append(escape(full)).append("</title>").append(escape(shown)).append("</text>");}if(!xs.isEmpty())for(int index=0;index<xs.size();index++){double x=left+(index+.5)*plotWidth/xs.size();out.append("<text x=\"").append(number(x)).append("\" y=\"").append(number(top+plotHeight+17)).append("\" font-size=\"10\" text-anchor=\"end\" transform=\"rotate(-30 ").append(number(x)).append(' ').append(number(top+plotHeight+17)).append(")\">").append(escape(xs.get(index))).append("</text>");}text(out,left+plotWidth/2,top+plotHeight+72,xAxis.getLabel()==null?"":xAxis.getLabel(),12,"middle");out.append("<text x=\"22\" y=\"").append(number(top+plotHeight/2)).append("\" font-size=\"12\" text-anchor=\"middle\" transform=\"rotate(-90 22 ").append(number(top+plotHeight/2)).append(")\">").append(escape(yAxis.getLabel())).append("</text><g clip-path=\"url(#plot-").append(chartIndex).append(")\">");appendRibbon(out,chart,xLow,xHigh,yLow,yHigh,left,top,plotWidth,plotHeight);int seriesIndex=0;for(var series:chart.getData()){if(chart.getProperties().get("brightstats.hiddenSeries") instanceof Set<?> hidden&&hidden.contains(seriesIndex)){seriesIndex++;continue;}String color=COLORS[seriesIndex%COLORS.length];StringBuilder path=new StringBuilder();boolean started=false;for(var point:series.getData()){double x=coordinate(point.getXValue(),xs,xLow,xHigh,left,plotWidth,false),y=coordinate(point.getYValue(),ys,yLow,yHigh,top,plotHeight,true);if(!Double.isFinite(x)||!Double.isFinite(y)){started=false;continue;}if(chart instanceof BarChart<?,?>){if(xs.isEmpty()||!ys.isEmpty())throw new IllegalArgumentException("SVG bars currently require category X and numeric Y axes.");double barWidth=plotWidth/xs.size()*.75/Math.max(1,chart.getData().size()),base=coordinate(0,List.of(),yLow,yHigh,top,plotHeight,true),x0=x-plotWidth/xs.size()*.375+seriesIndex*barWidth;out.append("<rect x=\"").append(number(x0)).append("\" y=\"").append(number(Math.min(y,base))).append("\" width=\"").append(number(barWidth)).append("\" height=\"").append(number(Math.abs(base-y))).append("\" fill=\"").append(color).append("\"><title>").append(escape(String.valueOf(point.getXValue())+": "+point.getYValue())).append("</title></rect>");}else if(chart instanceof LineChart<?,?>){path.append(started?'L':'M').append(number(x)).append(' ').append(number(y)).append(' ');started=true;}else{out.append("<circle cx=\"").append(number(x)).append("\" cy=\"").append(number(y)).append("\" r=\"4\" fill=\"").append(color).append("\"><title>").append(escape((point.getExtraValue()==null?"":point.getExtraValue()+": ")+point.getXValue()+", "+point.getYValue())).append("</title></circle>");}}if(!path.isEmpty())out.append("<path d=\"").append(path).append("\" fill=\"none\" stroke=\"").append(color).append("\" stroke-width=\"2\"/>");seriesIndex++;}out.append("</g>");seriesIndex=0;for(var series:chart.getData()){double x=left+(seriesIndex%3)*300,y=top+plotHeight+108+(seriesIndex/3)*20;out.append("<rect x=\"").append(number(x)).append("\" y=\"").append(number(y-10)).append("\" width=\"12\" height=\"12\" fill=\"").append(COLORS[seriesIndex%COLORS.length]).append("\"/>");text(out,x+18,y,(series.getName()==null?"Series "+(seriesIndex+1):series.getName())+(chart.getProperties().get("brightstats.hiddenSeries") instanceof Set<?> hidden&&hidden.contains(seriesIndex)?" (hidden)":""),11,"start");seriesIndex++;}}return out.append("</g></svg>").toString();}
}
